#include <linux/hid.h>
#include <linux/input.h>

int process_magic_input_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size) {
    void *drv_data = hid_get_drvdata(hdev);
    struct input_dev *input_dev = NULL;

    if (!drv_data) {
        return 0;
    }

    input_dev = ((struct magic_drvdata *)drv_data)->input_dev;
    if (!input_dev) {
        return 0;
    }

    switch (data[0]) {
        case TRACKPAD_REPORT_ID: {
            if (size < 4) {
                return 0;
            }
            int touch_count = data[1];
            if (touch_count < 0 || touch_count > MAX_TOUCHES) {
                return 0;
            }
            for (int i = 0; i < touch_count; i++) {
                int x = get_unaligned_le16(&data[2 + i * 4]);
                int y = get_unaligned_le16(&data[2 + i * 4 + 2]);
                input_report_abs(input_dev, ABS_MT_POSITION_X, x);
                input_report_abs(input_dev, ABS_MT_POSITION_Y, y);
            }
            break;
        }
        case MOUSE_REPORT_ID: {
            if (size < 4) {
                return 0;
            }
            int dx = data[1];
            int dy = data[2];
            input_report_rel(input_dev, REL_X, dx);
            input_report_rel(input_dev, REL_Y, dy);
            break;
        }
        case DOUBLE_REPORT_ID: {
            if (size < 8) {
                return 0;
            }
            int touch_count = data[1];
            if (touch_count < 0 || touch_count > MAX_TOUCHES) {
                return 0;
            }
            for (int i = 0; i < touch_count; i++) {
                int x = get_unaligned_le16(&data[2 + i * 4]);
                int y = get_unaligned_le16(&data[2 + i * 4 + 2]);
                input_report_abs(input_dev, ABS_MT_POSITION_X, x);
                input_report_abs(input_dev, ABS_MT_POSITION_Y, y);
            }
            int dx = data[6];
            int dy = data[7];
            input_report_rel(input_dev, REL_X, dx);
            input_report_rel(input_dev, REL_Y, dy);
            break;
        }
        default:
            return 0;
    }

    input_sync(input_dev);
    return 1;
}
